"use client";

import { useMemo, useState, type InputHTMLAttributes, type ReactNode } from "react";
import { useRouter } from "next/navigation";
import {
  ArrowLeft,
  ArrowLeftRight,
  ArrowRight,
  BadgeCheck,
  Building2,
  Check,
  CircleAlert,
  CircleCheck,
  ClipboardCheck,
  Coffee,
  CreditCard,
  DoorClosed,
  DoorOpen,
  Headset,
  House,
  Landmark,
  Lock,
  MailCheck,
  Pencil,
  Printer,
  ShieldCheck,
  Smile,
  TriangleAlert,
  User,
  Users,
  Wifi,
} from "lucide-react";
import styles from "./BookingFlow.module.css";
import type { BookingSummary } from "@/lib/booking";
import {
  EMPTY_PAY,
  TITLES,
  ageOk,
  addressOk,
  countryOk,
  phoneCodeOk,
  phoneDigitsOk,
  fitsSchema,
  buildBookingPayload,
  buildHotelBookingRecord,
  cardOk,
  cvvOk,
  emailOk,
  expiryOk,
  extractError,
  extractReference,
  extractStatus,
  formatCard,
  formatExpiry,
  makeClientReference,
  makeTravellers,
  nameOk,
  type BookingMeta,
  type Guest,
  type Pay,
  type Traveller,
} from "@/lib/booking-form";

const cx = (...a: (string | false | undefined)[]) => a.filter(Boolean).join(" ");

/* ------------------------------ form fields ------------------------------ */

function Field({
  id,
  label,
  error,
  floated,
  children,
}: {
  id: string;
  label: string;
  error?: string | false;
  floated?: boolean;
  children: ReactNode;
}) {
  return (
    <div className={cx(styles.field, !!error && styles.invalid, floated && styles.floated)}>
      {children}
      <label htmlFor={id}>{label}</label>
      {error && <div className={styles.feedback}>{error}</div>}
    </div>
  );
}

function TextField({
  id,
  label,
  value,
  onChange,
  error,
  type = "text",
  readOnly,
  extra,
}: {
  id: string;
  label: string;
  value: string;
  onChange: (v: string) => void;
  error?: string | false;
  type?: string;
  readOnly?: boolean;
  extra?: InputHTMLAttributes<HTMLInputElement>;
}) {
  return (
    <Field id={id} label={label} error={error} floated={type === "date"}>
      <input
        id={id}
        name={id}
        type={type}
        placeholder=" "
        value={value}
        readOnly={readOnly}
        onChange={(e) => onChange(e.target.value)}
        {...extra}
      />
    </Field>
  );
}

function SelectField({
  id,
  label,
  value,
  onChange,
  disabled,
}: {
  id: string;
  label: string;
  value: string;
  onChange: (v: string) => void;
  disabled?: boolean;
}) {
  return (
    <Field id={id} label={label} floated>
      <select id={id} name={id} value={value} disabled={disabled} onChange={(e) => onChange(e.target.value)}>
        {TITLES.map((t) => (
          <option key={t} value={t}>
            {t}
          </option>
        ))}
      </select>
    </Field>
  );
}

/* ------------------------------ summary card ----------------------------- */

function SummaryCard({
  summary,
  step,
  onChangeRoom,
}: {
  summary: BookingSummary;
  step: number;
  onChangeRoom: () => void;
}) {
  const s = summary;
  return (
    <div className={styles.summary}>
      <div className={styles.sumHero}>
        <small>
          <Building2 size={12} /> Your stay
        </small>
        <h5>{s.hotelName}</h5>
        <div className={styles.sumRoom}>
          <DoorOpen size={14} /> {s.roomName}
        </div>
        <div className={styles.sumRoom}>
          <Coffee size={14} /> {s.board}
        </div>
      </div>

      <div className={styles.sumBody}>
        <div className={styles.sumDates}>
          <div>
            <small>Check-in</small>
            <b>{s.checkIn}</b>
          </div>
          <div className={styles.sumNights}>
            <span>{s.nights}</span>
            <small>{s.nights === 1 ? "night" : "nights"}</small>
          </div>
          <div className={styles.right}>
            <small>Check-out</small>
            <b>{s.checkOut}</b>
          </div>
        </div>

        <div className={styles.sumGuests}>
          <Users size={15} /> {s.guests}
        </div>

        <div className={styles.sumPrices}>
          <div className={styles.sumRow}>
            <span>
              Room · {s.nights} {s.nights === 1 ? "night" : "nights"}
            </span>
            <span>{s.total}</span>
          </div>
          {s.perNight && (
            <div className={cx(styles.sumRow, styles.sub)}>
              <span>Average per night</span>
              <span>{s.perNight}</span>
            </div>
          )}
          {s.taxes.map((t) => (
            <div key={t.label} className={cx(styles.sumRow, styles.sub)}>
              <span>
                {t.label} <em>(pay at hotel)</em>
              </span>
              <span>{t.amount}</span>
            </div>
          ))}
        </div>

        <div className={styles.sumTotal}>
          <span>{s.payAtWeb ? "Total to pay now" : "Total (pay at hotel)"}</span>
          <strong>{s.total}</strong>
        </div>

        <div className={cx(styles.sumCancel, !s.refundable && styles.warn)}>
          {s.refundable ? <CircleCheck size={16} /> : <CircleAlert size={16} />}
          {s.cancel}
        </div>

        {step < 3 && (
          <button type="button" className={cx(styles.btnModify, styles.full)} onClick={onChangeRoom}>
            <ArrowLeftRight size={15} /> Change room
          </button>
        )}

        <ul className={styles.trust}>
          <li>
            <ShieldCheck size={15} /> Secure, encrypted booking
          </li>
          <li>
            <MailCheck size={15} /> Instant email confirmation
          </li>
          <li>
            <Headset size={15} /> 24/7 customer support
          </li>
        </ul>
      </div>
    </div>
  );
}

/* --------------------------------- page ---------------------------------- */

type Props = {
  summary: BookingSummary | null;
  meta: BookingMeta;
  error: string | null;
  hotelHref: string;
  adults: number;
  children: number;
  rooms: number;
};

export default function BookingFlow({ summary, meta, error, hotelHref, adults, children, rooms }: Props) {
  const router = useRouter();

  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [guest, setGuest] = useState<Guest>({ title: "Mr", firstName: "", lastName: "", email: "", phone: "" });
  const [phoneCode, setPhoneCode] = useState("");
  const [country, setCountry] = useState("");
  const [address, setAddress] = useState("");
  const [travellers, setTravellers] = useState<Traveller[]>(() => makeTravellers(adults, children));
  const [sameAsLead, setSameAsLead] = useState(true);
  const [marketing, setMarketing] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const [pay, setPay] = useState<Pay>(EMPTY_PAY);
  const [agree, setAgree] = useState(false);
  const [paySubmitted, setPaySubmitted] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [payError, setPayError] = useState("");
  const [reference, setReference] = useState("");

  // One reference per checkout session: retries reuse it so the same booking is never duplicated
  const [clientReference] = useState(() => makeClientReference());

  // traveller 1 mirrors the guest while "Same as guest" is on
  const travs = useMemo(
    () =>
      travellers.map((t, i) =>
        i === 0 && sameAsLead
          ? { ...t, title: guest.title, firstName: guest.firstName, lastName: guest.lastName }
          : t
      ),
    [travellers, sameAsLead, guest.title, guest.firstName, guest.lastName]
  );

  const setGuestField = (k: keyof Guest, v: string) => setGuest((g) => ({ ...g, [k]: v }));
  const setTrav = (i: number, k: keyof Traveller, v: string) =>
    setTravellers((list) => list.map((t, idx) => (idx === i ? { ...t, [k]: v } : t)));
  const setPayField = (k: keyof Pay, v: string) => setPay((p) => ({ ...p, [k]: v }));

  // when "Same as guest" is switched off, keep the names that were mirrored so far
  const toggleSameAsLead = (checked: boolean) => {
    if (!checked) {
      setTravellers((list) =>
        list.map((t, i) =>
          i === 0 ? { ...t, title: guest.title, firstName: guest.firstName, lastName: guest.lastName } : t
        )
      );
    }
    setSameAsLead(checked);
  };

  const guestValid =
    nameOk(guest.firstName) && fitsSchema(guest.firstName, 50) &&
    nameOk(guest.lastName) && fitsSchema(guest.lastName, 50) &&
    emailOk(guest.email) && fitsSchema(guest.email, 50) &&
    phoneDigitsOk(guest.phone) &&
    phoneCodeOk(phoneCode) &&
    countryOk(country) &&
    addressOk(address);

  const travValid = travs.every(
    (t) => nameOk(t.firstName) && nameOk(t.lastName) && (t.type === "adult" || ageOk(t.age))
  );

  const goStep = (s: 1 | 2 | 3) => {
    setStep(s);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const prev = () => (step === 1 ? router.push(hotelHref) : goStep((step - 1) as 1 | 2));

  function next(e: React.FormEvent) {
    e.preventDefault();
    setSubmitted(true);
    if (!guestValid || !travValid) return;
    goStep(2);
  }

  const payValid =
    nameOk(pay.name) && cardOk(pay.number) && expiryOk(pay.expiry) && cvvOk(pay.cvv);

  async function confirmBooking(e: React.FormEvent) {
    e.preventDefault();
    if (!summary || processing) return;

    setPaySubmitted(true);
    setPayError("");

    if (summary.payAtWeb && !payValid) return;
    if (!agree) {
      setPayError("Please accept the booking terms and cancellation policy to continue.");
      return;
    }

    setProcessing(true);
    try {
      // hotels_bookings record, built before the request so the server saves it as-is
      const booking = buildHotelBookingRecord({
        meta,
        guest,
        travellers: travs,
        address,
        country,
        phoneCountryCode: phoneCode,
        payAtWeb: summary.payAtWeb,
        clientReference,
      });

      const res = await fetch("/api/bookings", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...buildBookingPayload({
            rateKey: summary.rateKey,
            guest,
            travellers: travs,
            rooms,
            clientReference,
            pay: summary.payAtWeb ? pay : null,
          }),
          booking,
        }),
      });
      const json = await res.json().catch(() => null);

      if (!res.ok || json?.success === false) {
        setPayError(
          extractError(json) ?? "We couldn't complete your booking. Please check your details and try again."
        );
        return;
      }

      // Hotelbeds returns status CONFIRMED for a successful booking
      const status = extractStatus(json);
      if (status && status.toUpperCase() !== "CONFIRMED") {
        setPayError(`Your booking is not confirmed yet (status: ${status}). Please contact support before trying again.`);
        return;
      }

      setReference(extractReference(json) ?? clientReference);
      setPay(EMPTY_PAY); // never keep card data around after submitting
      goStep(3);
    } catch {
      setPayError(
        "We couldn't confirm your booking because of a network problem. Please check your email for a confirmation before trying again."
      );
    } finally {
      setProcessing(false);
    }
  }

  /* ----- no usable room: show a friendly message ----- */
  if (!summary) {
    return (
      <div className={styles.page}>
        <div className={styles.wrap}>
          <section className={cx(styles.panel, styles.centerPanel)}>
            <DoorClosed size={40} className={styles.emptyIco} />
            <h6>We couldn&apos;t load your room</h6>
            <p className={styles.mute}>{error ?? "No room selected yet."}</p>
            <button type="button" className={styles.btnBrand} onClick={() => router.push(hotelHref)}>
              Choose a room
            </button>
          </section>
        </div>
      </div>
    );
  }

  const stepClass = (n: number) =>
    cx(styles.st, step === n && styles.active, step > n && styles.done);

  return (
    <div className={styles.page}>
      <div className={styles.wrap}>
        {/* heading */}
        <div className={styles.pageHead}>
          <div>
            <h1>Complete your booking</h1>
            <p>You&apos;re almost there. It only takes a minute.</p>
          </div>
          <div className={styles.securePill}>
            <Lock size={14} /> Secure checkout
          </div>
        </div>

        {/* stepper */}
        <div className={styles.stepper}>
          <div className={stepClass(1)}>
            <span className={styles.dot}>{step > 1 ? <Check size={18} /> : <User size={18} />}</span>
            <span className={styles.txt}>
              <small>Step 1</small>
              <b>Guest details</b>
            </span>
          </div>

          <div className={styles.bar}>
            <i style={{ width: step > 1 ? "100%" : "0%" }} />
          </div>

          <div className={stepClass(2)}>
            <span className={styles.dot}>{step > 2 ? <Check size={18} /> : <CreditCard size={18} />}</span>
            <span className={styles.txt}>
              <small>Step 2</small>
              <b>Review &amp; payment</b>
            </span>
          </div>

          <div className={styles.bar}>
            <i style={{ width: step > 2 ? "100%" : "0%" }} />
          </div>

          <div className={stepClass(3)}>
            <span className={styles.dot}>
              <BadgeCheck size={18} />
            </span>
            <span className={styles.txt}>
              <small>Step 3</small>
              <b>Confirmation</b>
            </span>
          </div>
        </div>

        <div className={styles.layout}>
          {/* ============ LEFT ============ */}
          <div>
            {/* ---------- STEP 1 ---------- */}
            {step === 1 && (
              <form className={styles.stepPane} onSubmit={next} noValidate>
                <section className={styles.panel}>
                  <header className={styles.panelHead}>
                    <span className={styles.ico}>
                      <User size={20} />
                    </span>
                    <div>
                      <h6>Guest details</h6>
                      <small>We&apos;ll send your confirmation here</small>
                    </div>
                  </header>

                  <div className={styles.grid}>
                    <div className={styles.c3}>
                      <SelectField
                        id="gTitle"
                        label="Title"
                        value={guest.title}
                        onChange={(v) => setGuestField("title", v)}
                      />
                    </div>
                    <div className={styles.c4}>
                      <TextField
                        id="gFirst"
                        label="First name (max 50)"
                        value={guest.firstName}
                        onChange={(v) => setGuestField("firstName", v)}
                        error={
                          submitted &&
                          !(nameOk(guest.firstName) && fitsSchema(guest.firstName, 50)) &&
                          "Enter a valid first name"
                        }
                        extra={{ autoComplete: "given-name", maxLength: 50 }}
                      />
                    </div>
                    <div className={styles.c5}>
                      <TextField
                        id="gLast"
                        label="Last name (max 50)"
                        value={guest.lastName}
                        onChange={(v) => setGuestField("lastName", v)}
                        error={
                          submitted &&
                          !(nameOk(guest.lastName) && fitsSchema(guest.lastName, 50)) &&
                          "Enter a valid last name"
                        }
                        extra={{ autoComplete: "family-name", maxLength: 50 }}
                      />
                    </div>
                    <div className={styles.c5}>
                      <TextField
                        id="gEmail"
                        type="email"
                        label="Email address (max 50)"
                        value={guest.email}
                        onChange={(v) => setGuestField("email", v)}
                        error={
                          submitted &&
                          !(emailOk(guest.email) && fitsSchema(guest.email, 50)) &&
                          "Enter a valid email address"
                        }
                        extra={{ autoComplete: "email", maxLength: 50 }}
                      />
                    </div>
                    <div className={styles.c3}>
                      <TextField
                        id="gPhoneCode"
                        type="tel"
                        label="Country code (e.g. 92)"
                        value={phoneCode}
                        onChange={(v) => setPhoneCode(v.replace(/\D/g, "").slice(0, 4))}
                        error={submitted && !phoneCodeOk(phoneCode) && "Digits only"}
                        extra={{ inputMode: "numeric", maxLength: 4 }}
                      />
                    </div>
                    <div className={styles.c4}>
                      <TextField
                        id="gPhone"
                        type="tel"
                        label="Phone (no country code)"
                        value={guest.phone}
                        onChange={(v) => setGuestField("phone", v)}
                        error={submitted && !phoneDigitsOk(guest.phone) && "Enter 6 to 15 digits"}
                        extra={{ autoComplete: "tel-national" }}
                      />
                    </div>
                    <div className={styles.c6}>
                      <TextField
                        id="gCountry"
                        label="Country"
                        value={country}
                        onChange={setCountry}
                        error={submitted && !countryOk(country) && "Enter a valid country"}
                        extra={{ autoComplete: "country-name", maxLength: 50 }}
                      />
                    </div>
                    <div className={styles.c6}>
                      <TextField
                        id="gAddress"
                        label="Address (max 250)"
                        value={address}
                        onChange={setAddress}
                        error={submitted && !addressOk(address) && "Enter your address"}
                        extra={{ autoComplete: "street-address", maxLength: 250 }}
                      />
                    </div>
                  </div>
                </section>

                <section className={styles.panel}>
                  <header className={styles.panelHead}>
                    <span className={styles.ico}>
                      <Users size={20} />
                    </span>
                    <div>
                      <h6>Traveller details</h6>
                      <small>Names must match the travellers&apos; ID</small>
                    </div>
                  </header>

                  {travs.map((t, i) => {
                    const locked = i === 0 && sameAsLead;
                    return (
                      <div key={i} className={styles.trav}>
                        <div className={styles.travHead}>
                          <span className={styles.travBadge}>
                            {t.type === "adult" ? <User size={14} /> : <Smile size={14} />}
                            {t.label}
                          </span>
                          {i === 0 && (
                            <label className={cx(styles.check, styles.mlAuto)}>
                              <input
                                type="checkbox"
                                checked={sameAsLead}
                                onChange={(e) => toggleSameAsLead(e.target.checked)}
                              />
                              Same as guest
                            </label>
                          )}
                        </div>

                        <div className={styles.grid}>
                          <div className={styles.c3}>
                            <SelectField
                              id={`tTitle${i}`}
                              label="Title"
                              value={t.title}
                              disabled={locked}
                              onChange={(v) => setTrav(i, "title", v)}
                            />
                          </div>
                          <div className={styles.c3}>
                            <TextField
                              id={`tFirst${i}`}
                              label="First name"
                              value={t.firstName}
                              readOnly={locked}
                              onChange={(v) => setTrav(i, "firstName", v)}
                              error={submitted && !nameOk(t.firstName) && "Required"}
                            />
                          </div>
                          <div className={styles.c3}>
                            <TextField
                              id={`tLast${i}`}
                              label="Last name"
                              value={t.lastName}
                              readOnly={locked}
                              onChange={(v) => setTrav(i, "lastName", v)}
                              error={submitted && !nameOk(t.lastName) && "Required"}
                            />
                          </div>
                          <div className={styles.c3}>
                            {t.type === "adult" ? (
                              <TextField
                                id={`tDob${i}`}
                                type="date"
                                label="Birth date (optional)"
                                value={t.dob}
                                onChange={(v) => setTrav(i, "dob", v)}
                              />
                            ) : (
                              <TextField
                                id={`tAge${i}`}
                                type="number"
                                label="Age at check-out"
                                value={t.age}
                                onChange={(v) => setTrav(i, "age", v)}
                                error={submitted && !ageOk(t.age) && "Enter age 0–17"}
                                extra={{ min: 0, max: 17 }}
                              />
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })}

                  <label className={cx(styles.check, styles.mt)}>
                    <input type="checkbox" checked={marketing} onChange={(e) => setMarketing(e.target.checked)} />
                    <span className={styles.mute}>Send me booking updates and special offers from Travelshop Booking</span>
                  </label>
                </section>

                <div className={styles.actions}>
                  <button type="button" className={styles.btnLine} onClick={prev}>
                    <ArrowLeft size={16} /> Back
                  </button>
                  <button type="submit" className={styles.btnBrand}>
                    Continue to payment <ArrowRight size={16} />
                  </button>
                </div>
              </form>
            )}

            {/* ---------- STEP 2 ---------- */}
            {step === 2 && (
              <div className={styles.stepPane}>
                <section className={styles.panel}>
                  <header className={styles.panelHead}>
                    <span className={styles.ico}>
                      <ClipboardCheck size={20} />
                    </span>
                    <div>
                      <h6>Review your details</h6>
                      <small>Check everything is correct</small>
                    </div>
                    <button type="button" className={cx(styles.btnModify, styles.mlAuto)} onClick={() => goStep(1)}>
                      <Pencil size={14} /> Edit
                    </button>
                  </header>

                  <div className={styles.reviewGrid}>
                    <div>
                      <small>Guest</small>
                      <b>
                        {guest.title} {guest.firstName} {guest.lastName}
                      </b>
                    </div>
                    <div>
                      <small>Email</small>
                      <b>{guest.email}</b>
                    </div>
                    <div>
                      <small>Phone</small>
                      <b>
                        +{phoneCode} {guest.phone}
                      </b>
                    </div>
                    <div>
                      <small>Country</small>
                      <b>{country}</b>
                    </div>
                    <div>
                      <small>Address</small>
                      <b>{address}</b>
                    </div>
                  </div>

                  <div className={styles.reviewList}>
                    {travs.map((t, i) => (
                      <div key={i} className={styles.reviewTrav}>
                        <span className={styles.av}>{(t.firstName || "?").charAt(0).toUpperCase()}</span>
                        <span>
                          {t.title} {t.firstName} {t.lastName}
                        </span>
                        <small className={cx(styles.mute, styles.mlAuto)}>
                          {t.label}
                          {t.type === "child" && ` · age ${t.age}`}
                        </small>
                      </div>
                    ))}
                  </div>

                  {summary.rateComments && (
                    <div className={styles.notice}>
                      <b>Important information</b>
                      <p>{summary.rateComments}</p>
                    </div>
                  )}
                </section>

                <form onSubmit={confirmBooking} noValidate>
                  <section className={styles.panel}>
                    <header className={styles.panelHead}>
                      <span className={styles.ico}>
                        <CreditCard size={20} />
                      </span>
                      <div>
                        <h6>Payment</h6>
                        <small>{summary.payAtWeb ? "Your card details are encrypted" : "Nothing to pay today"}</small>
                      </div>
                      {summary.payAtWeb && (
                        <span className={cx(styles.accepted, styles.mlAuto)}>
                          <CreditCard size={20} />
                          <Landmark size={20} />
                        </span>
                      )}
                    </header>

                    {summary.payAtWeb ? (
                      <div className={styles.payGrid}>
                        <div className={styles.grid}>
                          <div className={styles.c12}>
                            <TextField
                              id="cName"
                              label="Name on card"
                              value={pay.name}
                              onChange={(v) => setPayField("name", v)}
                              error={paySubmitted && !nameOk(pay.name) && "Required"}
                              extra={{ autoComplete: "cc-name" }}
                            />
                          </div>
                          <div className={styles.c12}>
                            <TextField
                              id="cNumber"
                              label="Card number"
                              value={pay.number}
                              onChange={(v) => setPayField("number", formatCard(v))}
                              error={paySubmitted && !cardOk(pay.number) && "Enter a valid card number"}
                              extra={{ inputMode: "numeric", autoComplete: "cc-number", maxLength: 23 }}
                            />
                          </div>
                          <div className={styles.c6}>
                            <TextField
                              id="cExp"
                              label="Expiry (MM/YY)"
                              value={pay.expiry}
                              onChange={(v) => setPayField("expiry", formatExpiry(v))}
                              error={paySubmitted && !expiryOk(pay.expiry) && "Invalid date"}
                              extra={{ inputMode: "numeric", autoComplete: "cc-exp", maxLength: 5 }}
                            />
                          </div>
                          <div className={styles.c6}>
                            <TextField
                              id="cCvv"
                              type="password"
                              label="CVV"
                              value={pay.cvv}
                              onChange={(v) => setPayField("cvv", v.replace(/\D/g, "").slice(0, 4))}
                              error={paySubmitted && !cvvOk(pay.cvv) && "Invalid"}
                              extra={{ inputMode: "numeric", autoComplete: "cc-csc", maxLength: 4 }}
                            />
                          </div>
                        </div>

                        {/* live card preview */}
                        <div className={styles.cardPreview} aria-hidden>
                          <div className={styles.cpTop}>
                            <span className={styles.cpChip} />
                            <Wifi size={20} />
                          </div>
                          <div className={styles.cpNumber}>{pay.number || "•••• •••• •••• ••••"}</div>
                          <div className={styles.cpBottom}>
                            <div>
                              <small>Card holder</small>
                              <b>{pay.name || "YOUR NAME"}</b>
                            </div>
                            <div className={styles.right}>
                              <small>Expires</small>
                              <b>{pay.expiry || "MM/YY"}</b>
                            </div>
                          </div>
                        </div>
                      </div>
                    ) : (
                      <p className={styles.mute}>
                        This rate is paid at the hotel. Your booking is confirmed now and you pay {summary.total} when you
                        stay.
                      </p>
                    )}

                    <label className={cx(styles.check, styles.mtLg)}>
                      <input type="checkbox" checked={agree} onChange={(e) => setAgree(e.target.checked)} />
                      I agree to the booking terms and cancellation policy
                    </label>

                    {payError && (
                      <div className={styles.alertDanger}>
                        <TriangleAlert size={16} /> {payError}
                      </div>
                    )}
                  </section>

                  <div className={styles.actions}>
                    <button type="button" className={styles.btnLine} onClick={prev} disabled={processing}>
                      <ArrowLeft size={16} /> Back
                    </button>
                    <button type="submit" className={styles.btnBrand} disabled={processing}>
                      {processing ? (
                        <>
                          <span className={styles.spinner} /> Processing...
                        </>
                      ) : (
                        <>
                          <Lock size={16} /> {summary.payAtWeb ? `Pay ${summary.total}` : "Confirm booking"}
                        </>
                      )}
                    </button>
                  </div>
                </form>
              </div>
            )}

            {/* ---------- STEP 3 ---------- */}
            {step === 3 && (
              <div className={styles.stepPane}>
                <section className={cx(styles.panel, styles.donePanel)}>
                  <div className={styles.doneIco}>
                    <Check size={38} />
                  </div>
                  <h3>Booking confirmed!</h3>
                  <p className={styles.mute}>
                    A confirmation email will be sent to <b>{guest.email}</b>
                  </p>

                  <div className={styles.ticket}>
                    <div className={styles.ticketTop}>
                      <small>Booking reference</small>
                      <strong>{reference}</strong>
                    </div>
                    <div className={styles.ticketBody}>
                      <div className={styles.tHotel}>{summary.hotelName}</div>
                      <div className={styles.tRoom}>
                        {summary.roomName} · {summary.board}
                      </div>
                      <div className={styles.tGrid}>
                        <div>
                          <small>Check-in</small>
                          <b>{summary.checkIn}</b>
                        </div>
                        <div>
                          <small>Check-out</small>
                          <b>{summary.checkOut}</b>
                        </div>
                        <div>
                          <small>Guests</small>
                          <b>{summary.guests}</b>
                        </div>
                        <div>
                          <small>{summary.payAtWeb ? "Total paid" : "Total (pay at hotel)"}</small>
                          <b>{summary.total}</b>
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className={styles.doneActions}>
                    <button type="button" className={styles.btnLine} onClick={() => window.print()}>
                      <Printer size={16} /> Print
                    </button>
                    <button type="button" className={styles.btnBrand} onClick={() => router.push("/")}>
                      <House size={16} /> Back to home
                    </button>
                  </div>
                </section>
              </div>
            )}
          </div>

          {/* ============ RIGHT ============ */}
          <aside>
            <SummaryCard summary={summary} step={step} onChangeRoom={() => router.push(hotelHref)} />
          </aside>
        </div>
      </div>
    </div>
  );
}