// lib/booking-form.ts

export const TITLES = ["Mr", "Mrs", "Ms", "Miss", "Dr"] as const;

export type Guest = {
  title: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
};

export type Traveller = {
  type: "adult" | "child";
  label: string;
  title: string;
  firstName: string;
  lastName: string;
  dob: string; // adults, optional
  age: string; // children, required
};

export type Pay = { name: string; number: string; expiry: string; cvv: string };

export const EMPTY_PAY: Pay = { name: "", number: "", expiry: "", cvv: "" };

export function makeTravellers(adults: number, children: number): Traveller[] {
  const base = { title: "Mr", firstName: "", lastName: "", dob: "", age: "" };
  return [
    ...Array.from({ length: Math.max(1, adults) }, (_, i) => ({
      ...base,
      type: "adult" as const,
      label: i === 0 ? "Adult 1 (lead traveller)" : `Adult ${i + 1}`,
    })),
    ...Array.from({ length: Math.max(0, children) }, (_, i) => ({
      ...base,
      type: "child" as const,
      label: `Child ${i + 1}`,
    })),
  ];
}

/**
 * Hotelbeds allows max 20 characters for clientReference.
 * "TSB" (3) + base36 timestamp (~8) + 3 random chars = ~14.
 * Create it ONCE per checkout session and reuse it on retries.
 */
export function makeClientReference(): string {
  const time = Date.now().toString(36).toUpperCase();
  const rand = Math.random().toString(36).slice(2, 5).toUpperCase().padEnd(3, "X");
  return `TSB${time}${rand}`.slice(0, 20);
}

/* ------------------------------ validation ------------------------------ */

export const emailOk = (v: string) => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim());

// Hotelbeds rejects digits / symbols in names, so require 2+ letters
export const nameOk = (v: string) => /^[\p{L}][\p{L} .'-]+$/u.test(v.trim());

export const phoneOk = (v: string) => /^\+?[\d\s()-]{6,}$/.test(v.trim());

export const ageOk = (v: string) => /^\d{1,2}$/.test(v) && Number(v) <= 17;

export function cardOk(v: string): boolean {
  const d = v.replace(/\s/g, "");
  if (!/^\d{13,19}$/.test(d)) return false;
  let sum = 0;
  let alt = false;
  for (let i = d.length - 1; i >= 0; i--) {
    let n = Number(d[i]);
    if (alt) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    alt = !alt;
  }
  return sum % 10 === 0;
}

export function expiryOk(v: string): boolean {
  const m = /^(\d{2})\/(\d{2})$/.exec(v);
  if (!m) return false;
  const mm = Number(m[1]);
  const yy = Number(m[2]);
  if (mm < 1 || mm > 12) return false;
  // valid through the last second of the expiry month
  return new Date(2000 + yy, mm, 0, 23, 59, 59).getTime() >= Date.now();
}

export const cvvOk = (v: string) => /^\d{3,4}$/.test(v);

/* ------------------------------ formatting ------------------------------ */

export const formatCard = (v: string) =>
  v.replace(/\D/g, "").slice(0, 19).replace(/(.{4})/g, "$1 ").trim();

export function formatExpiry(v: string): string {
  const d = v.replace(/\D/g, "").slice(0, 4);
  return d.length >= 3 ? `${d.slice(0, 2)}/${d.slice(2)}` : d;
}

// Hotelbeds card codes
export function cardType(number: string): string {
  const d = number.replace(/\s/g, "");
  if (/^4/.test(d)) return "VI"; // Visa
  // Mastercard: 51-55 and 2221-2720
  if (/^(5[1-5]\d{2}|222[1-9]|22[3-9]\d|2[3-6]\d{2}|27[01]\d|2720)/.test(d)) return "CA";
  if (/^3[47]/.test(d)) return "AX"; // American Express
  if (/^3(0|6|8)/.test(d)) return "DC"; // Diners
  return "";
}

/* ------------------------------ API payload ----------------------------- */

/**
 * Standard Hotelbeds booking request, sent to our Next.js route which forwards it
 * to the Node backend (POST /api/v1/hotels/bookings).
 * `pay` is only passed for rates that are paid online (paymentType AT_WEB).
 */
export function buildBookingPayload(a: {
  rateKey: string;
  guest: Guest;
  travellers: Traveller[];
  rooms: number;
  clientReference: string;
  pay: Pay | null;
}) {
  const rooms = Math.max(1, a.rooms);
  const adults = a.travellers.filter((t) => t.type === "adult");
  const children = a.travellers.filter((t) => t.type === "child");

  const paxes = [
    ...adults.map((t, i) => ({
      roomId: (i % rooms) + 1,
      type: "AD" as const,
      name: t.firstName.trim(),
      surname: t.lastName.trim(),
    })),
    ...children.map((t, i) => ({
      roomId: (i % rooms) + 1,
      type: "CH" as const,
      age: Number(t.age),
      name: t.firstName.trim(),
      surname: t.lastName.trim(),
    })),
  ];

  return {
    holder: { name: a.guest.firstName.trim(), surname: a.guest.lastName.trim() },
    rooms: [{ rateKey: a.rateKey, paxes }],
    clientReference: a.clientReference,
    remark: "",
    tolerance: 2,
    ...(a.pay
      ? {
          paymentData: {
            paymentCard: {
              cardType: cardType(a.pay.number),
              cardNumber: a.pay.number.replace(/\s/g, ""),
              cardHolderName: a.pay.name.trim(),
              expiryDate: a.pay.expiry.replace("/", ""), // MMYY
              cardCVC: a.pay.cvv,
            },
            contactData: { email: a.guest.email.trim(), phoneNumber: a.guest.phone.trim() },
          },
        }
      : {}),
  };
}

/* ------------------------------ API response ---------------------------- */

function str(v: unknown): string | null {
  return typeof v === "string" && v.trim() ? v.trim() : null;
}

export function extractReference(json: any): string | null {
  return (
    str(json?.data?.booking?.reference) ??
    str(json?.data?.data?.booking?.reference) ??
    str(json?.booking?.reference) ??
    str(json?.data?.reference) ??
    str(json?.reference)
  );
}

/** Hotelbeds booking status, e.g. CONFIRMED */
export function extractStatus(json: any): string | null {
  return (
    str(json?.data?.booking?.status) ??
    str(json?.data?.data?.booking?.status) ??
    str(json?.booking?.status) ??
    null
  );
}

export function extractError(json: any): string | null {
  return (
    str(json?.message) ??
    str(json?.error?.message) ??
    str(json?.data?.error?.message) ??
    str(json?.error)
  );
}

/* ------------------------ hotels_bookings record ------------------------ */

export type HotelMeta = {
  id: number;
  name: string;
  stars: string;
  phone: string;
  email: string;
  website: string;
  address: string;
  img: string;
  location: string;
  locationCords: string;
};

export type BookingMeta = {
  hotel: HotelMeta;
  checkIn: string; // YYYY-MM-DD
  checkOut: string; // YYYY-MM-DD
  price: number; // numeric total, e.g. 245.5
  currency: string; // e.g. "EUR"
  taxes: number; // pay-at-hotel taxes, 0 if none
  roomName: string;
  board: string;
  supplier: string; // "Hotelbeds"
};

export type BookingRecordInput = {
  meta: BookingMeta;
  guest: Guest;
  travellers: Traveller[];
  address: string;
  country: string;
  phoneCountryCode: string;
  payAtWeb: boolean;
  clientReference: string;
  userId?: string | null;
};

const digitsOnly = (v: string) => v.replace(/\D/g, "");

/** Builds a document matching the hotels_bookings Mongoose schema exactly. Card data is never included. */
export function buildHotelBookingRecord(a: BookingRecordInput) {
  const m = a.meta;
  const children = a.travellers.filter((t) => t.type === "child");
  const nights = Math.round((Date.parse(m.checkOut) - Date.parse(m.checkIn)) / 86400000);
  const guestNames = a.travellers
    .map((t) => `${t.title} ${t.firstName.trim()} ${t.lastName.trim()}`.trim())
    .join(", ");

  return {
    booking_ref_no: null,
    booking_date: new Date(),
    booking_status: "pending",
    price_original: m.price,
    price_markup: null,
    vat: "0",
    tax: String(m.taxes),
    gst: 0,
    first_name: a.guest.firstName.trim(),
    last_name: a.guest.lastName.trim(),
    email: a.guest.email.trim(),
    address: a.address.trim(),
    phone_country_code: Number(digitsOnly(a.phoneCountryCode)),
    phone: Number(digitsOnly(a.guest.phone)),
    country: a.country.trim(),
    stars: m.hotel.stars,
    hotel_id: m.hotel.id,
    hotel_name: m.hotel.name,
    hotel_phone: Number(digitsOnly(m.hotel.phone)),
    hotel_email: m.hotel.email,
    hotel_website: m.hotel.website,
    hotel_address: m.hotel.address,
    room_data: `${m.roomName} · ${m.board}`.slice(0, 500),
    location: m.hotel.location,
    location_cords: m.hotel.locationCords,
    hotel_img: m.hotel.img,
    checkin: m.checkIn,
    checkout: m.checkOut,
    booking_nights: nights,
    adults: a.travellers.length - children.length,
    childs: children.length,
    child_ages: children.length ? children.map((c) => c.age).join(",") : "N/A",
    currency_original: m.currency,
    currency_markup: null,
    payment_date: null,
    cancellation_request: 0,
    cancellation_status: 0,
    booking_data: null,
    payment_status: "unpaid",
    supplier: m.supplier,
    transaction_id: a.clientReference,
    user_id: a.userId ?? null,
    user_data: JSON.stringify({
      guest: {
        title: a.guest.title,
        firstName: a.guest.firstName,
        lastName: a.guest.lastName,
        email: a.guest.email,
        phone: a.guest.phone,
      },
      travellers: a.travellers,
    }),
    guest: guestNames,
    nationality: null,
    payment_gateway: a.payAtWeb ? "AT_WEB" : null,
    module_type: "hotels",
    pnr: null,
    booking_response: null,
    error_response: null,
    agent_markup_price: null,
    agent_net_profit: null,
    agent_markup_percent: null,
    agent_markup: null,
  };
}

/* ------------------------- extra validation ----------------------------- */

export const addressOk = (v: string) => v.trim().length >= 5 && v.trim().length <= 250;
export const countryOk = (v: string) => /^[\p{L}][\p{L} .'-]{1,49}$/u.test(v.trim());
export const phoneCodeOk = (v: string) => /^\d{1,4}$/.test(v.trim());
export const phoneDigitsOk = (v: string) => /^\d{6,15}$/.test(digitsOnly(v));
export const fitsSchema = (v: string, max: number) => v.trim().length <= max;